    ('3260', 230, 27, 19, 307, 741, 1113),
    ('3261', 334, 12, 37, 513, 1160, 2596),
    ('3262', 336, 31, 25, 577, 1278, 2168),
    ('3263', 236, 16, 35, 409, 919, 1572),
    ('3264', 240, 18, 12, 365, 860, 1913),
    ('3265', 235, 24, 22, 391, 897, 1734),
    ('3266', 339, 35, 35, 524, 1222, 2372),
    ('3267', 271, 25, 18, 401, 899, 1738),
    ('3268', 344, 50, 31, 730, 1585, 2782),
    ('3269', 233, 22, 17, 178, 555, 930),
    ('3270', 591, 50, 27, 271, 1098, 2133),
    ('3271', 396, 63, 30, 272, 928, 2199),
    ('3272', 54, 3, 16, 93, 209, 671),
    ('3273', 58, 2, 13, 266, 422, 864),
    ('3274', 174, 20, 19, 525, 918, 1764),
    ('3275', 158, 42, 46, 583, 1179, 2982),
    ('3276', 172, 18, 54, 241, 606, 1162),
    ('3277', 182, 46, 38, 738, 1261, 3437)
), cargado AS (
  SELECT s.section_code,
         COUNT(*) AS party_rows,
         MAX(r.votes) FILTER (WHERE p.party_code='PAN') AS pan,
         MAX(r.votes) FILTER (WHERE p.party_code='PRI') AS pri,
         MAX(r.votes) FILTER (WHERE p.party_code='PVEM') AS pvem,
         MAX(r.votes) FILTER (WHERE p.party_code='MORENA') AS morena,
         MAX(r.total_votes) AS total_votes,
         MAX(r.nominal_list) AS nominal_list
  FROM electoral.section_result r
  JOIN electoral.election e ON e.election_id=r.election_id
  JOIN electoral.party p ON p.party_id=r.party_id
  JOIN territorial.section s ON s.section_id=r.section_id
  WHERE e.election_year=2024 AND e.election_type='P'
  GROUP BY s.section_code
), c AS (
  SELECT o.*, d.party_rows, d.pan AS db_pan, d.pri AS db_pri,
         d.pvem AS db_pvem, d.morena AS db_morena,
         d.total_votes AS db_total, d.nominal_list AS db_ln
  FROM oficial o LEFT JOIN cargado d USING (section_code)
)
SELECT '01_resumen_P_2024' AS bloque,
       COUNT(*) AS secciones_fuente,
       COUNT(*) FILTER (WHERE party_rows IS NULL) AS sin_filas_db,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL) AS con_filas_db,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND party_rows<>4) AS con_partidos_incompletos,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND db_pan IS DISTINCT FROM pan) AS pan_distinto,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND db_pri IS DISTINCT FROM pri) AS pri_distinto,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND db_pvem IS DISTINCT FROM pvem) AS pvem_distinto,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND db_morena IS DISTINCT FROM morena) AS morena_distinto,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND db_total IS DISTINCT FROM total_votes) AS total_distinto,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND db_ln IS DISTINCT FROM nominal_list) AS ln_distinta,
       COUNT(*) FILTER (WHERE party_rows IS NOT NULL AND (db_pan,db_pri,db_pvem,db_morena,db_total,db_ln)
                         IS DISTINCT FROM (pan,pri,pvem,morena,total_votes,nominal_list)) AS secciones_con_alguna_diferencia
FROM c;

SELECT '02_caso_1150' AS bloque,s.section_code,p.party_code,r.votes,r.total_votes,r.nominal_list
FROM electoral.section_result r
JOIN electoral.election e ON e.election_id=r.election_id
JOIN electoral.party p ON p.party_id=r.party_id
JOIN territorial.section s ON s.section_id=r.section_id
WHERE e.election_year=2024 AND e.election_type='P' AND s.section_code='1150'
ORDER BY p.party_code;
